def handle(app, svc):
    resp = svc.apply(app)
    result = resp.get("result", {})
    outcome = result.get("outcome", "")
    credit_limit = result.get("credit_limit", 0)

    # Network referral rule: self_employed with requested_limit strictly above 4000
    # must be queue_review instead of issued (regardless of partner decision).
    # A decline stays a decline.
    if (app.get("employment") == "self_employed"
            and app.get("requested_limit", 0) > 4000
            and outcome == "approved"):
        return {"action": "queue_review", "limit": 0}

    if outcome == "approved":
        return {"action": "issue", "limit": credit_limit}
    elif outcome == "manual_review":
        return {"action": "queue_review", "limit": 0}
    elif outcome == "declined":
        return {"action": "decline", "limit": 0}
    else:
        return {"action": "queue_review", "limit": 0}
